from __future__ import annotations

from typing import Any


def adapt_input(payload: dict[str, Any]) -> dict[str, Any]:
    return {
        "task_id": str(payload.get("task_id", "")).strip(),
        "source_id": str(payload.get("source_id", "")).strip(),
        "payload": dict(payload.get("payload", {}) or {}),
        "priority": int(payload.get("priority", 0)),
        "tags": [str(item).strip() for item in payload.get("tags", []) if str(item).strip()],
    }


def step_fetch(data: dict[str, Any]) -> dict[str, Any]:
    source_id = str(data.get("source_id", "")).strip()
    if not source_id:
        return {"ok": False, "reason": "missing_source", "value": {}}
    return {"ok": True, "reason": "fetched", "value": {"source_id": source_id, "raw": dict(data.get("payload", {}))}}


def step_transform(data: dict[str, Any]) -> dict[str, Any]:
    raw = dict(data.get("raw", {}))
    value = str(raw.get("value", "")).strip()
    if not value:
        return {"ok": False, "reason": "missing_value", "value": {}}
    return {"ok": True, "reason": "transformed", "value": {"normalized_value": value.lower(), "length": len(value)}}


def step_persist(data: dict[str, Any]) -> dict[str, Any]:
    value = str(data.get("normalized_value", "")).strip()
    if not value:
        return {"ok": False, "reason": "invalid_persist_payload", "value": {}}
    return {"ok": True, "reason": "persisted", "value": {"record_id": f"rec-{value}", "length": int(data.get("length", 0))}}


def build_output(task_id: str, persisted: dict[str, Any]) -> dict[str, Any]:
    return {
        "task_id": task_id,
        "record_id": str(persisted.get("record_id", "")).strip(),
        "length": int(persisted.get("length", 0)),
    }


def enrich_output(output: dict[str, Any], tags: list[str]) -> dict[str, Any]:
    item = dict(output)
    item["tags"] = [str(tag).strip() for tag in tags if str(tag).strip()]
    item["tag_count"] = len(item["tags"])
    return item


def is_retryable_reason(reason: str) -> bool:
    normalized = reason.strip().lower()
    return normalized in {"missing_value", "missing_source"}


def summarize_steps(step_results: list[dict[str, Any]]) -> dict[str, int]:
    success = 0
    failed = 0
    for result in step_results:
        if bool(result.get("ok", False)):
            success += 1
        else:
            failed += 1
    return {"success": success, "failed": failed}


def coerce_priority(raw: Any) -> int:
    if isinstance(raw, bool):
        return 0
    try:
        value = int(raw)
    except Exception:
        return 0
    if value < 0:
        return 0
    if value > 10:
        return 10
    return value

