from __future__ import annotations

from typing import Any


DEFAULTS = {
    "max_retries": 1,
    "timeout_ms": 1200,
    "allow_async_mode": True,
    "emit_debug": False,
    "batch_limit": 100,
}


class Config:
    def __init__(self) -> None:
        self._values: dict[str, Any] = dict(DEFAULTS)

    def load(self) -> dict[str, Any]:
        return dict(self._values)

    def update(self, values: dict[str, Any]) -> None:
        for key, value in values.items():
            self._values[str(key)] = value

    def get_int(self, key: str, fallback: int) -> int:
        raw = self._values.get(key, fallback)
        if isinstance(raw, bool):
            return fallback
        try:
            return int(raw)
        except Exception:
            return fallback

    def get_bool(self, key: str, fallback: bool) -> bool:
        raw = self._values.get(key, fallback)
        if isinstance(raw, bool):
            return raw
        if isinstance(raw, str):
            text = raw.strip().lower()
            if text in {"true", "1", "yes"}:
                return True
            if text in {"false", "0", "no"}:
                return False
        return fallback

    def reset(self) -> None:
        self._values = dict(DEFAULTS)

    def ensure_defaults(self) -> None:
        for key, value in DEFAULTS.items():
            if key not in self._values:
                self._values[key] = value

    def validate(self) -> list[str]:
        errors: list[str] = []
        if self.get_int("max_retries", 0) < 0:
            errors.append("max_retries")
        if self.get_int("timeout_ms", 0) <= 0:
            errors.append("timeout_ms")
        if self.get_int("batch_limit", 0) <= 0:
            errors.append("batch_limit")
        return errors

