from dataclasses import dataclass
from threading import Lock
from typing import Any


@dataclass(frozen=True)
class Event:
    event_type: str
    task_id: str
    payload: dict[str, Any]


class EventLog:
    def __init__(self) -> None:
        self._lock = Lock()
        self._events: list[Event] = []

    def add(self, event_type: str, task_id: str, payload: dict[str, Any]) -> None:
        item = Event(
            event_type=event_type.strip() or "unknown",
            task_id=task_id.strip(),
            payload=dict(payload),
        )
        with self._lock:
            self._events.append(item)

    def list_all(self) -> list[Event]:
        with self._lock:
            return list(self._events)

    def by_task(self, task_id: str) -> list[Event]:
        target = task_id.strip()
        with self._lock:
            return [item for item in self._events if item.task_id == target]

    def by_type(self, event_type: str) -> list[Event]:
        target = event_type.strip()
        with self._lock:
            return [item for item in self._events if item.event_type == target]

    def count(self) -> int:
        with self._lock:
            return len(self._events)

    def clear(self) -> None:
        with self._lock:
            self._events.clear()

    def summary(self) -> dict[str, int]:
        with self._lock:
            out: dict[str, int] = {}
            for item in self._events:
                out[item.event_type] = out.get(item.event_type, 0) + 1
            return out

    def latest_for_task(self, task_id: str) -> Event | None:
        items = self.by_task(task_id)
        if not items:
            return None
        return items[-1]

