from __future__ import annotations

from threading import Lock


class Metrics:
    def __init__(self) -> None:
        self._lock = Lock()
        self._values: dict[str, int] = {}

    def incr(self, key: str, amount: int = 1) -> None:
        metric = key.strip()
        if not metric:
            return
        with self._lock:
            self._values[metric] = self._values.get(metric, 0) + amount

    def get(self, key: str) -> int:
        metric = key.strip()
        if not metric:
            return 0
        with self._lock:
            return self._values.get(metric, 0)

    def snapshot(self) -> dict[str, int]:
        with self._lock:
            return dict(self._values)

    def reset(self) -> None:
        with self._lock:
            self._values.clear()

    def merge(self, other: "Metrics") -> None:
        values = other.snapshot()
        with self._lock:
            for key, value in values.items():
                self._values[key] = self._values.get(key, 0) + int(value)

    def keys(self) -> list[str]:
        with self._lock:
            return sorted(self._values.keys())

    def total(self) -> int:
        with self._lock:
            return sum(self._values.values())

    def top_keys(self, limit: int = 5) -> list[tuple[str, int]]:
        items = self.snapshot().items()
        ranked = sorted(items, key=lambda item: item[1], reverse=True)
        return ranked[: max(0, int(limit))]

    def export_lines(self) -> list[str]:
        return [f"{key}={value}" for key, value in sorted(self.snapshot().items())]

    def has_activity(self) -> bool:
        return self.total() > 0

    def percentile_like(self, ratio: float) -> int:
        values = sorted(self.snapshot().values())
        if not values:
            return 0
        if ratio <= 0:
            return values[0]
        if ratio >= 1:
            return values[-1]
        index = int((len(values) - 1) * ratio)
        return values[index]

