from __future__ import annotations

from dataclasses import dataclass
from typing import Any


@dataclass(frozen=True)
class ScheduledItem:
    task_id: str
    priority: int
    payload: dict[str, Any]


class Scheduler:
    def __init__(self) -> None:
        self._queue: list[ScheduledItem] = []

    def enqueue(self, task_id: str, priority: int, payload: dict[str, Any]) -> None:
        item = ScheduledItem(task_id=task_id.strip(), priority=int(priority), payload=dict(payload))
        self._queue.append(item)
        self._queue.sort(key=lambda value: (-value.priority, value.task_id))

    def dequeue(self) -> ScheduledItem | None:
        if not self._queue:
            return None
        return self._queue.pop(0)

    def count(self) -> int:
        return len(self._queue)

    def clear(self) -> None:
        self._queue.clear()

    def snapshot(self) -> list[dict[str, Any]]:
        return [{"task_id": item.task_id, "priority": item.priority, "payload": dict(item.payload)} for item in self._queue]

    def has(self, task_id: str) -> bool:
        key = task_id.strip()
        return any(item.task_id == key for item in self._queue)

    def remove(self, task_id: str) -> bool:
        key = task_id.strip()
        before = len(self._queue)
        self._queue = [item for item in self._queue if item.task_id != key]
        return len(self._queue) != before

    def top(self, limit: int = 3) -> list[dict[str, Any]]:
        out = self.snapshot()
        return out[: max(0, int(limit))]

    def priorities(self) -> list[int]:
        return [item.priority for item in self._queue]

    def highest_priority(self) -> int:
        if not self._queue:
            return 0
        return max(item.priority for item in self._queue)

    def lowest_priority(self) -> int:
        if not self._queue:
            return 0
        return min(item.priority for item in self._queue)

