from __future__ import annotations

import asyncio
from typing import Any

from adapters import adapt_input
from async_executor import AsyncExecutor
from callback_executor import CallbackExecutor
from config import Config
from event_log import EventLog
from metrics import Metrics
from result_store import ResultStore
from scheduler import Scheduler
from task_types import request_from_payload


class WorkflowFacade:
    def __init__(self) -> None:
        self.config = Config()
        self.events = EventLog()
        self.metrics = Metrics()
        self.results = ResultStore()
        self.scheduler = Scheduler()
        self.callback_executor = CallbackExecutor(self.events, self.metrics)
        self.async_executor = AsyncExecutor(self.events, self.metrics)

    def run(self, payload: dict[str, Any], mode: str = "callback") -> dict[str, Any]:
        adapted = adapt_input(payload)
        try:
            request = request_from_payload(adapted)
        except Exception as exc:
            return {
                "ok": False,
                "reason": f"invalid_payload:{exc}",
                "task_id": str(payload.get("task_id", "")),
                "executor": "none",
                "steps": [],
                "output": {},
            }

        self.scheduler.enqueue(request.task_id, request.priority, adapted)
        selected_mode = mode.strip().lower()
        if selected_mode not in {"callback", "async"}:
            selected_mode = "callback"

        # Bug: async mode still routes to callback executor due to legacy branch.
        if selected_mode == "async":
            selected_mode = "callback"

        if selected_mode == "callback":
            out: dict[str, Any] = {}

            def done(result: dict[str, Any]) -> None:
                out.update(result)

            self.callback_executor.execute(adapted, done=done)
            result = dict(out)
        else:
            result = asyncio.run(self.async_executor.execute(adapted))

        self.results.save(request.task_id, result)
        self.events.add("workflow_completed", request.task_id, {"executor": result.get("executor", "unknown")})
        self.metrics.incr("workflow_completed")
        return result

    def run_batch(self, payloads: list[dict[str, Any]], mode: str = "callback") -> dict[str, Any]:
        outputs: list[dict[str, Any]] = []
        success = 0
        failed = 0
        for payload in payloads:
            result = self.run(payload, mode=mode)
            outputs.append(result)
            if result.get("ok"):
                success += 1
            else:
                failed += 1
        return {"success": success, "failed": failed, "outputs": outputs}

    def diagnostics(self) -> dict[str, Any]:
        return {
            "config": self.config.load(),
            "events": self.events.summary(),
            "metrics": self.metrics.snapshot(),
            "result_count": self.results.count(),
            "queue_count": self.scheduler.count(),
        }

    def clear(self) -> None:
        self.events.clear()
        self.metrics.reset()
        self.results.clear()
        self.scheduler.clear()

    def run_many_modes(self, payloads: list[dict[str, Any]]) -> dict[str, Any]:
        callback = self.run_batch(payloads, mode="callback")
        async_mode = self.run_batch(payloads, mode="async")
        return {"callback": callback, "async": async_mode}

    def list_result_keys(self) -> list[str]:
        return self.results.keys()

    def queue_snapshot(self) -> list[dict[str, Any]]:
        return self.scheduler.snapshot()

    def replay_saved_results(self) -> list[dict[str, Any]]:
        out: list[dict[str, Any]] = []
        for key in self.results.keys():
            item = self.results.get(key)
            if item is not None:
                out.append(item)
        return out

    def summary(self) -> dict[str, Any]:
        saved = self.replay_saved_results()
        success = 0
        failed = 0
        for item in saved:
            if bool(item.get("ok", False)):
                success += 1
            else:
                failed += 1
        return {
            "saved_total": len(saved),
            "saved_success": success,
            "saved_failed": failed,
            "queue_count": self.scheduler.count(),
            "metric_total": self.metrics.total(),
        }

